export interface DoorConfig {
  readonly loc: number;
  readonly replaceId: number;
  readonly fence: boolean;
  readonly autowalk: boolean;
}

const DOOR_CONFIGS: ReadonlyMap<number, DoorConfig> = (() => {
  const map = new Map<number, DoorConfig>();
  for (const [closed, open, fence, autowalk] of DOOR_PAIRS) {
    // Last write wins in both directions, matching the rev-530 loader; several closed ids share one
    // open id (e.g. 3/1530/1591 -> 1531), so the reverse lookup of a shared open id is ambiguous.
    // Runtime close always uses the remembered original leaf, never this reverse entry.
    map.set(closed, Object.freeze({ loc: closed, replaceId: open, fence, autowalk }));
    map.set(open, Object.freeze({ loc: open, replaceId: closed, fence, autowalk }));
  }
  return map;
})();

/** Look up the door pair containing `loc` (either the closed or the open id). */
export function doorConfigFor(loc: number): DoorConfig | undefined {
  return DOOR_CONFIGS.get(loc);
}
